# ============================================================
# AEGIS NIDS - Phase 21 Deploy Script (Security + Dashboard Cleanup)
# ============================================================
$ErrorActionPreference = 'Stop'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS Phase 21 - Security Holes + Dashboard Cleanup"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"

function Deploy-File {
    param([string]$RelativePath, [string]$Base64Content, [int]$ExpectedLines)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $Dir = Split-Path $FullPath -Parent
    if (-not (Test-Path $Dir)) { New-Item -ItemType Directory -Path $Dir -Force | Out-Null }
    $BackupPath = "$FullPath.phase21_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
        Write-Host "  [OK] Backup created"
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] Line count: actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] Deployed: $ActualLines lines (expected $ExpectedLines)"
    }
}

$B64_1 = ''
Deploy-File -RelativePath "core/bridge_init.zig" -ExpectedLines 587 -Base64Content $B64_1

$B64_2 = ''
Deploy-File -RelativePath "core/nids_analyze.zig" -ExpectedLines 2163 -Base64Content $B64_2

$B64_3 = ''
Deploy-File -RelativePath "bridge/aegis_ipc.hpp" -ExpectedLines 370 -Base64Content $B64_3

$B64_4 = ''
Deploy-File -RelativePath "bridge/aegis_ipc.cpp" -ExpectedLines 425 -Base64Content $B64_4

$B64_5 = ''
Deploy-File -RelativePath "aegis_dashboard/Cargo.toml" -ExpectedLines 19 -Base64Content $B64_5


Write-Host ""
Write-Host "[INFO] Phase 21 also requires manual cleanup on Windows:"
Write-Host "  - Delete orphan files: aegis_dashboard\src\bridge_ffi.rs data.rs db.rs rules.rs udp.rs"
Write-Host "  - Delete directory: aegis_dashboard\src\handlers\"
Write-Host ""
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | ForEach-Object { Write-Host $_ }
if ($LASTEXITCODE -eq 0) {
    Write-Host "[BUILD] SUCCESS - All Phase 21 fixes applied"
} else {
    Write-Host "[BUILD] FAILED"
    exit 1
}

Write-Host ""
Write-Host "Summary of changes:"
Write-Host "  Phase 21 changes (Security Holes + Dashboard Cleanup):"
Write-Host "    B-05:  bridge_init.zig: Added magic(0x41454749) + version + struct_size to IpcEvent (ABI safety)"
Write-Host "           + validateIpcEvent() function + updated pushTier1Match/pushForwardedEvent"
Write-Host "    B-06:  bridge/aegis_ipc.hpp: Added std::mutex to SharedRingBuffer (was data race on m_head/m_tail)"
Write-Host "           - All Push/Pop/Count/Dropped/IsEmpty/IsFull now use std::lock_guard"
Write-Host "    B-07:  bridge/aegis_ipc.cpp: Implemented aegis_bridge_block_ip/unblock_ip via netsh advfirewall"
Write-Host "           (was: fprintf only, returned false success - IPS was non-functional)"
Write-Host "    GAP-5: aegis_dashboard: Deleted 6 orphan source files (bridge_ffi.rs, data.rs, db.rs, rules.rs, udp.rs, handlers/)"
Write-Host "           + removed 9 unused Cargo.toml dependencies (axum, tokio, dashmap, tracing, etc.)"
Write-Host "    Effect: 3 security holes closed + dashboard cleaned up"

Write-Host ""
Write-Host "Suggested git commands:"
Write-Host "  git add -A"
Write-Host "  git commit -m `"fix: best practices phase 21 - security holes + dashboard cleanup`""
Write-Host "  git push"
